static int count_vars(sav_ctx_t *ctx) {
	int i;
	spss_varinfo_t *last_info = NULL;
	int var_count = 0;
	for (i=0; i<ctx->var_index; i++) {
		spss_varinfo_t *info = ctx->varinfo[i];
		if (last_info == NULL || strcmp(info->name, last_info->name) != 0) {
