static int handle_metadata(readstat_metadata_t *metadata, void *ctx) { return READSTAT_HANDLER_OK; }
static int handle_note(int index, const char *note, void *ctx) { return READSTAT_HANDLER_OK; }
static int handle_fweight(readstat_variable_t *variable, void *ctx) { return READSTAT_HANDLER_OK; }
static int handle_variable(int index, readstat_variable_t *variable, const char *val_labels, void *ctx) { return READSTAT_HANDLER_OK; }
static int handle_value(int obs_index, readstat_variable_t *variable, readstat_value_t value, void *ctx) { return READSTAT_HANDLER_OK; }
static int handle_value_label(const char *val_labels, readstat_value_t value, const char *label, void *ctx) { return READSTAT_HANDLER_OK; }

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    readstat_parser_t *parser = readstat_parser_init();
